from collections import Counter
from copy import deepcopy
from datetime import datetime
from typing import Any

_WEEKDAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")


def _validated(rows: list[dict[str, Any]]) -> list[tuple[dict[str, Any], datetime]]:
    if not isinstance(rows, list):
        raise ValueError("rows must be a list")
    result = []
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("each row must be a dictionary")
        required = ("started_at", "entrance", "exit", "minutes", "membership")
        if any(key not in row for key in required):
            raise ValueError("row is missing a required field")
        try:
            parsed = datetime.strptime(row["started_at"], "%Y-%m-%dT%H:%M")
        except (TypeError, ValueError):
            raise ValueError("invalid started_at") from None
        if parsed.strftime("%Y-%m-%dT%H:%M") != row["started_at"]:
            raise ValueError("started_at must use strict formatting")
        for key in ("entrance", "exit", "membership"):
            if not isinstance(row[key], str) or not row[key]:
                raise ValueError(f"{key} must be a non-empty string")
        minutes = row["minutes"]
        if not isinstance(minutes, (int, float)) or isinstance(minutes, bool) or minutes < 0:
            raise ValueError("minutes must be non-negative numeric data")
        age = row.get("age_group")
        if age is not None and (not isinstance(age, str) or not age):
            raise ValueError("age_group must be null or a non-empty string")
        result.append((row, parsed))
    return result


def _mode(counter: Counter, order=None):
    if not counter:
        return None
    highest = max(counter.values())
    tied = [key for key, value in counter.items() if value == highest]
    return min(tied, key=order) if order else min(tied)


def summarize_visits(rows, zone=None, weekday=None):
    validated = _validated(rows)
    if zone is not None and (not isinstance(zone, str) or not zone):
        raise ValueError("zone must be null or a non-empty string")
    if weekday is not None and (not isinstance(weekday, str) or not weekday):
        raise ValueError("weekday must be null or a non-empty string")
    normalized_weekday = None
    if weekday is not None:
        matches = [name for name in _WEEKDAYS if name.casefold() == weekday.casefold()]
        if not matches:
            raise ValueError("invalid weekday")
        normalized_weekday = matches[0]

    selected = [
        (row, stamp) for row, stamp in validated
        if (zone is None or row["entrance"].casefold() == zone.casefold())
        and (normalized_weekday is None or stamp.strftime("%A") == normalized_weekday)
    ]
    months = Counter(stamp.month for _, stamp in selected)
    weekdays = Counter(stamp.strftime("%A") for _, stamp in selected)
    hours = Counter(stamp.hour for _, stamp in selected)
    entrances = Counter(row["entrance"] for row, _ in selected)
    exits = Counter(row["exit"] for row, _ in selected)
    routes = Counter((row["entrance"], row["exit"]) for row, _ in selected)
    memberships = Counter(row["membership"] for row, _ in selected)
    ages = Counter(row["age_group"] for row, _ in selected if row.get("age_group") is not None)
    total = sum(row["minutes"] for row, _ in selected)

    return {
        "count": len(selected),
        "month": _mode(months),
        "weekday": _mode(weekdays, lambda value: _WEEKDAYS.index(value)),
        "hour": _mode(hours),
        "entrance": _mode(entrances),
        "exit": _mode(exits),
        "route": _mode(routes),
        "total_minutes": total,
        "average_minutes": total / len(validated) if validated else 0,
        "memberships": dict(sorted(memberships.items())),
        "age_groups": dict(sorted(ages.items())),
    }


def page_rows(rows, offset, size=5):
    _validated(rows)
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError("offset must be a non-negative integer")
    if not isinstance(size, int) or isinstance(size, bool) or size <= 0:
        raise ValueError("size must be a positive integer")
    return deepcopy(rows[offset:offset + size])

